  -- 4. THE CARRY GATE. Every chair kept is carried into a Season 2 rung whose TEXT still says
  --    what the Season 1 rung said. Re-assert it here so a later ladder revision cannot
  --    silently move a chair this migration preserved.
  SELECT count(*) INTO n
    FROM (VALUES
      ('0bc588c6-39e1-4084-b5de-cac909b8b762'::uuid, 1),
      ('0bc588c6-39e1-4084-b5de-cac909b8b762'::uuid, 2),
      ('44905f3b-e105-4f6c-afc7-5d223813dbac'::uuid, 1),
      ('9db07b16-1076-4b7d-ad89-ebe7b51f4336'::uuid, 1),
      ('9db07b16-1076-4b7d-ad89-ebe7b51f4336'::uuid, 2),
      ('af2fdfd6-02c4-49df-b09c-cf8536f4773f'::uuid, 1),
      ('af2fdfd6-02c4-49df-b09c-cf8536f4773f'::uuid, 2),
      ('af2fdfd6-02c4-49df-b09c-cf8536f4773f'::uuid, 4),
      ('b9ccee94-ad96-4f10-b655-889d8e5abe92'::uuid, 1),
      ('c267e137-0ff9-4e7d-9d13-e3cea1756cd0'::uuid, 1),
      ('c308e8e8-caac-44f5-ab04-dbfecf40bbe2'::uuid, 2),
      ('cab61e8a-64fe-4bbd-bc08-fe9914d0091b'::uuid, 1),
      ('e8dad4a8-eb93-4931-91f5-d8fb5d7dd529'::uuid, 1),
      ('e9ebefcd-c496-45e8-b816-a79f8442ba85'::uuid, 2),
      ('e9ebefcd-c496-45e8-b816-a79f8442ba85'::uuid, 4)
    ) AS k(tid, val)
    JOIN inform.season_questions q1 ON q1.topic_id = k.tid AND q1.season_id = '2d5d67d1-2a2a-4c73-88bb-3c2e3e33cba3'
    JOIN inform.season_questions q2 ON q2.topic_id = k.tid AND q2.season_id = '86d893a1-c1a2-4bbf-b4e5-69ec43221194'
    JOIN inform.compass_stance_revisions r1
      ON r1.topic_revision_id = q1.topic_revision_id AND r1.value = k.val
    JOIN inform.compass_stance_revisions r2
      ON r2.topic_revision_id = q2.topic_revision_id AND r2.value = k.val
    JOIN inform.compass_topics t ON t.id = k.tid
   WHERE r1.text IS DISTINCT FROM r2.text
     -- four rungs were reworded without changing what they ask; each was read in full and
     -- is named here so the exemption is auditable rather than a blanket tolerance.
     AND (t.topic_key, k.val) NOT IN (('deportation', 1), ('judicial-criminal-justice', 1),
                                      ('judicial-criminal-justice', 2), ('civil-rights', 1));
  IF n <> 0 THEN
    RAISE EXCEPTION 'migration 1900: % carried chairs sit on a Season 2 rung whose text has changed -- re-read before repairing', n;
  END IF;

  -- 5. voting-rights must still be the REWRITTEN (voter-ID) ladder that forced 14 blanks
  SELECT count(*) INTO n FROM inform.season_questions q
    JOIN inform.compass_topics t ON t.id = q.topic_id
    JOIN inform.compass_stance_revisions r ON r.topic_revision_id = q.topic_revision_id
   WHERE q.season_id = '86d893a1-c1a2-4bbf-b4e5-69ec43221194' AND t.topic_key = 'voting-rights' AND r.value = 1
     AND r.text ILIKE '%identification%';
  IF n <> 1 THEN
    RAISE EXCEPTION 'migration 1900: Season 2 voting-rights rung 1 is no longer the voter-ID rung -- the 14 ladder-scope blanks need re-reading (found %)', n;
  END IF;
END
